select count(*) > 0 from enrollment
where student_id = #{studentId} and class_id = #{classId}
  and status = 'ENROLLED'

mapper.insert:
insert into enrollment (
student_id, class_id, term_id, status,
grade, grade_status, enroll_time, drop_time,
create_by, create_time, update_by, update_time, remark
) values (
#{studentId}, #{classId}, #{termId}, #{status},
#{grade}, #{gradeStatus}, #{enrollTime}, #{dropTime},
#{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

mapper.update:
update enrollment
status = #{status}, grade = #{grade}, grade_status = #{gradeStatus}, drop_time = #{dropTime}, enroll_time = #{enrollTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where enrollment_id = #{enrollmentId}

update enrollment
set grade_status = #{gradeStatus}
where class_id = #{classId}

mapper.select:
select class_id from enrollment
where student_id = #{studentId}
  and status = 'ENROLLED'


where student_id = #{studentId}

    and term_id = #{termId}


    and grade_status = #{gradeStatus}

order by enroll_time desc

select e.enrollment_id, e.student_id, e.class_id, e.term_id, e.status, e.grade, e.grade_status, e.enroll_time, e.drop_time, c.course_name, c.course_code, c.credit_hours from enrollment e left join course_class cc on cc.class_id = e.class_id left join course c on c.course_id = cc.course_id where e.student_id = #{studentId}
and e.term_id = #{termId}
and e.grade_status = #{gradeStatus}
order by e.enroll_time desc

